import {
  Editable as EditablePrimitive,
  useEditable,
  useEditableContext,
} from '@ark-ui/solid/editable';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { children, Show, splitProps } from 'solid-js';
import { CheckIcon, CloseIcon, PencilIcon } from '@/lib/moduix/icons/ui/Icons';
import styles from './Editable.module.css';

function EditableRoot(props: ComponentProps<typeof EditablePrimitive.Root>) {
  const [local, others] = splitProps(props, ['activationMode', 'class']);

  return (
    <EditablePrimitive.Root
      activationMode={local.activationMode ?? 'dblclick'}
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="editable-root"
    />
  );
}

function EditableRootProvider(props: ComponentProps<typeof EditablePrimitive.RootProvider>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <EditablePrimitive.RootProvider
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="editable-root-provider"
    />
  );
}

function EditableLabel(props: ComponentProps<typeof EditablePrimitive.Label>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <EditablePrimitive.Label
      class={clsx(styles.label, local.class)}
      {...others}
      data-slot="editable-label"
    />
  );
}

function EditableArea(props: ComponentProps<typeof EditablePrimitive.Area>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <EditablePrimitive.Area
      class={clsx(styles.area, local.class)}
      {...others}
      data-slot="editable-area"
    />
  );
}

function EditableInput(props: ComponentProps<typeof EditablePrimitive.Input>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <EditablePrimitive.Input
      class={clsx(styles.input, local.class)}
      {...others}
      data-slot="editable-input"
    />
  );
}

function EditablePreview(props: ComponentProps<typeof EditablePrimitive.Preview>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <EditablePrimitive.Preview
      class={clsx(styles.preview, local.class)}
      {...others}
      data-slot="editable-preview"
    />
  );
}

function EditableControl(props: ComponentProps<typeof EditablePrimitive.Control>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <EditablePrimitive.Control
      class={clsx(styles.control, local.class)}
      {...others}
      data-slot="editable-control"
    />
  );
}

function EditableEditTrigger(props: ComponentProps<typeof EditablePrimitive.EditTrigger>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <EditablePrimitive.EditTrigger
      class={clsx(styles.trigger, local.class)}
      {...others}
      data-slot="editable-edit-trigger"
    >
      {resolvedChildren() ?? <PencilIcon />}
    </EditablePrimitive.EditTrigger>
  );
}

function EditableSubmitTrigger(props: ComponentProps<typeof EditablePrimitive.SubmitTrigger>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <EditablePrimitive.SubmitTrigger
      class={clsx(styles.trigger, local.class)}
      {...others}
      data-slot="editable-submit-trigger"
    >
      {resolvedChildren() ?? <CheckIcon />}
    </EditablePrimitive.SubmitTrigger>
  );
}

function EditableCancelTrigger(props: ComponentProps<typeof EditablePrimitive.CancelTrigger>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <EditablePrimitive.CancelTrigger
      class={clsx(styles.trigger, local.class)}
      {...others}
      data-slot="editable-cancel-trigger"
    >
      {resolvedChildren() ?? <CloseIcon />}
    </EditablePrimitive.CancelTrigger>
  );
}

type EditableControlsProps = Omit<
  ComponentProps<typeof EditablePrimitive.Control>,
  'asChild' | 'children'
>;

function EditableControls(props: EditableControlsProps) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <EditableControl class={local.class} {...others}>
      <EditablePrimitive.Context>
        {(editable) => (
          <Show when={editable().editing} fallback={<EditableEditTrigger />}>
            <EditableSubmitTrigger />
            <EditableCancelTrigger />
          </Show>
        )}
      </EditablePrimitive.Context>
    </EditableControl>
  );
}

const Editable = Object.assign(EditableRoot, {
  Root: EditableRoot,
  RootProvider: EditableRootProvider,
  Label: EditableLabel,
  Area: EditableArea,
  Input: EditableInput,
  Preview: EditablePreview,
  Control: EditableControl,
  EditTrigger: EditableEditTrigger,
  SubmitTrigger: EditableSubmitTrigger,
  CancelTrigger: EditableCancelTrigger,
  Controls: EditableControls,
  Context: EditablePrimitive.Context,
});

export { Editable, useEditable, useEditableContext };

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: inline-grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    row-gap: var(--moduix-editable-gap, var(--moduix-spacing-1));
    column-gap: var(--moduix-editable-control-gap, var(--moduix-spacing-1));
    width: var(--moduix-editable-width, auto);
    max-width: var(--moduix-editable-max-width, 100%);
    color: var(--moduix-editable-color, var(--moduix-color-foreground));

    &:has(.area[data-disabled]) {
      opacity: var(--moduix-editable-disabled-opacity, var(--moduix-opacity-disabled));
    }
  }

  .label {
    grid-column: 1 / -1;
    display: inline-flex;
    align-items: center;
    gap: var(--moduix-editable-label-gap, var(--moduix-spacing-1));
    color: var(--moduix-editable-label-color, var(--moduix-color-foreground));
    font-size: var(--moduix-editable-label-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-editable-label-font-weight, var(--moduix-weight-medium));
    line-height: var(--moduix-editable-label-line-height, var(--moduix-line-height-text-sm));

    &[data-invalid] {
      color: var(--moduix-editable-label-color-invalid, var(--moduix-color-destructive));
    }
  }

  .area {
    --_editable-focus-ring-width: var(
      --moduix-editable-focus-ring-width,
      var(
        --moduix-editable-border-width,
        var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
      )
    );

    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    grid-column: 1;
    width: var(--moduix-editable-area-width, 100%);
    min-width: 0;
    min-height: var(--moduix-editable-area-height, var(--moduix-size-md));
    border: var(--moduix-editable-border-width, var(--moduix-border-width-sm))
      var(--moduix-editable-border-style, solid)
      var(--moduix-editable-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-editable-radius, var(--moduix-radius-md));
    padding: var(--moduix-editable-padding-y, var(--moduix-spacing-1))
      var(--moduix-editable-padding-x, var(--moduix-spacing-3-5));
    background-color: var(--moduix-editable-bg, var(--moduix-color-background));
    color: var(--moduix-editable-color, var(--moduix-color-foreground));
    outline: var(--_editable-focus-ring-width) solid transparent;
    outline-offset: calc(var(--_editable-focus-ring-width) * -1);
    transition:
      border-color var(--moduix-editable-transition, var(--moduix-transition-default)),
      outline-color var(--moduix-editable-transition, var(--moduix-transition-default)),
      opacity var(--moduix-editable-transition, var(--moduix-transition-default));

    &[data-focus] {
      outline-color: var(--moduix-editable-focus-ring-color, var(--moduix-color-ring));
    }

    &:has(
      .input:is([data-invalid], [aria-invalid='true']),
      .preview:is([data-invalid], [aria-invalid='true'])
    ) {
      border-color: var(--moduix-editable-border-color-invalid, var(--moduix-color-destructive));

      &[data-focus] {
        outline-color: var(--moduix-editable-border-color-invalid, var(--moduix-color-destructive));
      }
    }

    &[data-disabled] {
      pointer-events: none;
    }
  }

  .input,
  .preview {
    box-sizing: border-box;
    display: block;
    width: var(--moduix-editable-input-width, 100%);
    min-width: 0;
    margin: 0;
    border: 0;
    padding: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    font-size: var(--moduix-editable-font-size, var(--moduix-text-md));
    line-height: var(--moduix-editable-line-height, var(--moduix-line-height-text-md));
    outline: 0;
  }

  .input {
    appearance: none;

    &::placeholder {
      color: var(--moduix-editable-placeholder-color, var(--moduix-color-muted-foreground));
    }

    &:is(textarea) {
      min-height: var(--moduix-editable-textarea-min-height, 6rem);
      resize: var(--moduix-editable-textarea-resize, vertical);
    }
  }

  .preview {
    min-height: var(--moduix-editable-preview-min-height, 1lh);
    cursor: text;

    &[data-placeholder-shown] {
      color: var(--moduix-editable-placeholder-color, var(--moduix-color-muted-foreground));
    }

    &:is([data-disabled], [data-readonly], [aria-readonly='true']) {
      cursor: default;
    }
  }

  .control {
    display: inline-flex;
    grid-column: 2;
    align-items: center;
    align-self: var(--moduix-editable-control-align, center);
    gap: var(--moduix-editable-control-gap, var(--moduix-spacing-1));
  }

  .trigger {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(
      --moduix-editable-trigger-size,
      var(--moduix-editable-area-height, var(--moduix-size-md))
    );
    min-width: var(
      --moduix-editable-trigger-size,
      var(--moduix-editable-area-height, var(--moduix-size-md))
    );
    height: var(
      --moduix-editable-trigger-size,
      var(--moduix-editable-area-height, var(--moduix-size-md))
    );
    margin: 0;
    border: var(--moduix-editable-trigger-border-width, var(--moduix-border-width-sm))
      var(--moduix-editable-trigger-border-style, solid)
      var(--moduix-editable-trigger-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-editable-trigger-radius, var(--moduix-radius-sm));
    padding: 0;
    background-color: var(--moduix-editable-trigger-bg, var(--moduix-color-background));
    color: var(--moduix-editable-trigger-color, var(--moduix-color-foreground));
    outline: var(
        --moduix-editable-focus-ring-width,
        var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
      )
      solid transparent;
    outline-offset: calc(
      0px -
        var(
          --moduix-editable-focus-ring-width,
          var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        )
    );
    cursor: pointer;
    transition:
      background-color var(--moduix-editable-transition, var(--moduix-transition-default)),
      border-color var(--moduix-editable-transition, var(--moduix-transition-default)),
      color var(--moduix-editable-transition, var(--moduix-transition-default)),
      outline-color var(--moduix-editable-transition, var(--moduix-transition-default)),
      opacity var(--moduix-editable-transition, var(--moduix-transition-default));

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-editable-trigger-bg-hover, var(--moduix-color-accent));
      }
    }

    &:active {
      background-color: var(
        --moduix-editable-trigger-bg-active,
        var(--moduix-editable-trigger-bg-hover, var(--moduix-color-accent))
      );
    }

    &:focus-visible,
    &[data-focus] {
      outline-color: var(--moduix-editable-focus-ring-color, var(--moduix-color-ring));
    }

    &:is([data-disabled], :disabled) {
      pointer-events: none;
      opacity: var(--moduix-editable-disabled-opacity, var(--moduix-opacity-disabled));
    }

    & > svg {
      width: var(--moduix-editable-trigger-icon-size, var(--moduix-spacing-3-5));
      height: var(--moduix-editable-trigger-icon-size, var(--moduix-spacing-3-5));
      flex-shrink: 0;
    }
  }
}
